import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const maxDataPoints = 10; // Número máximo de puntos en la gráfica

    // Función para generar un valor aleatorio
    const generateRandomPrice = () => {
        return (Math.random() * 10 + 15).toFixed(2); // Genera un precio entre 15 y 25
    };

    // Función para actualizar los datos
    const updateData = () => {
        setData((prevData) => {
            const newDataPoint = { name: `T-${prevData.length}`, price: generateRandomPrice() };
            const updatedData = [...prevData, newDataPoint];

            // Si hay más de 10 puntos, elimina los más antiguos
            return updatedData.length > maxDataPoints ? updatedData.slice(updatedData.length - maxDataPoints) : updatedData;
        });
    };

    useEffect(() => {
        updateData(); // Llama la función al inicio
        const interval = setInterval(updateData, 10000); // Actualiza cada 10 segundos
        return () => clearInterval(interval); // Limpia el intervalo al desmontar
    }, []);

    return (
        <div style={{ width: '10cm', height: '10cm' }}> {/* Establece el tamaño a 10cm */}
            <ResponsiveContainer width="100%" height="100%">
                <LineChart data={data}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" interval={0} />
                    <YAxis tickFormatter={(value) => `$${value}`} />
                    <Tooltip formatter={(value) => [`$${value}`, 'Precio Aleatorio']} />
                    <Legend />
                    <Line type="monotone" dataKey="price" stroke="#8884d8" strokeWidth={2} animationDuration={500} /> {/* Añade duración de la animación */}
                </LineChart>
            </ResponsiveContainer>
        </div>
    );
};

export default Graph;
